    .story-card a:hover,
    .collection-highlight a:hover,
    .deal-card a:hover {
      text-decoration: underline;
    }

    .story-card .meta-text {
      font-size: 0.92rem;
    }

    .newsletter-form {
      display: grid;
      gap: 0.75rem;
      margin-top: 1rem;
    }

    .newsletter-form label {
      font-weight: 700;
    }

    .newsletter-form input {
      width: 100%;
      padding: 0.9rem 1rem;
      border-radius: 1rem;
      border: 1px solid var(--color-border-strong);
      background: #fff;
      color: var(--color-text);
    }

    .inline-note {
      min-height: 1.5rem;
      margin: 0;
      color: var(--color-muted-text);
      font-size: 0.95rem;
    }

    .site-footer {
      padding: 2rem 0 3rem;
      border-top: 1px solid var(--color-border);
    }

    .footer-grid {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: 1rem;
      color: var(--color-muted-text);
    }

    .footer-grid nav ul {
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
      list-style: none;
      margin: 0;
      padding: 0;
    }

    .visually-hidden {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0 0 0 0);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 1040px) {
      .hero,
      .editorial-grid {
        grid-template-columns: 1fr;
      }

      .collections-grid,
      .deals-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .product-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }
    }

    @media (max-width: 720px) {
      .site-shell {
        width: min(calc(100% - 1rem), var(--max-width));
      }

      .promo-content,
      .masthead,
      .section-top,
      .price-row {
        align-items: flex-start;
      }

      .collections-grid,
      .deals-grid,
      .product-grid {
        grid-template-columns: 1fr;
      }

      .search-form {
        width: 100%;
      }

      .search-form input {
        min-width: 0;
        width: 100%;
      }

      .hero-panel {
        min-height: auto;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      html {
        scroll-behavior: auto;
      }

      *,
      *::before,
      *::after {
        animation: none !important;
        transition: none !important;
      }
    }

    @media (forced-colors: active) {
      body {
        background: Canvas;
        color: CanvasText;
      }

      .promo-bar,
      .site-header,
      .hero-panel,
      .hero-aside,
      .collection-highlight,
      .deal-card,
      .story-card,
      .newsletter-panel,
      .product-card,
      .search-form,
      .filter-button,
      .button,
      .button-secondary {
        background: Canvas;
        color: CanvasText;
        border: 1px solid ButtonBorder;
        box-shadow: none;
      }

      .button,
      .button-secondary,
      .filter-button[aria-pressed="true"] {
        background: ButtonFace;
        color: ButtonText;
      }

      a {
        color: LinkText;
      }

      a:focus-visible,
      button:focus-visible,
      input:focus-visible {
        outline: 3px solid Highlight;
      }
    }
  </style>
</head>
