      z-index: 100;
      padding: 0.75rem 1rem;
      border-radius: 0.75rem;
      background: var(--color-text);
      color: #fff;
      transform: translateY(-180%);
      transition: transform 0.2s ease;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    .site-shell {
      width: min(calc(100% - 2rem), var(--max-width));
      margin: 0 auto;
    }

    .promo-bar {
      border-bottom: 1px solid var(--color-border);
      background: rgba(255, 255, 255, 0.75);
      backdrop-filter: blur(16px);
    }

    .promo-content,
    .masthead {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 0.9rem 0;
    }

    .promo-copy {
      margin: 0;
      color: var(--color-muted-text);
      font-size: 0.96rem;
    }

    .text-button {
      border: 0;
      background: none;
      color: var(--color-text);
      padding: 0.35rem 0.55rem;
      border-radius: 0.65rem;
      cursor: pointer;
      font-weight: 600;
    }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 20;
      background: rgba(252, 250, 247, 0.88);
      backdrop-filter: blur(18px);
      border-bottom: 1px solid rgba(216, 206, 194, 0.7);
    }

    .masthead {
      padding: 1rem 0;
      flex-wrap: wrap;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.8rem;
      font-weight: 700;
      text-decoration: none;
      letter-spacing: 0.02em;
    }

    .brand-mark {
      width: 2.35rem;
      height: 2.35rem;
      border-radius: 50%;
      background:
        radial-gradient(circle at 35% 35%, #f6efe8 0 18%, #f6efe800 19%),
        linear-gradient(135deg, var(--color-accent), #2b7b6e);
      box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.35);
    }

    .site-nav ul {
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .site-nav a {
      text-decoration: none;
      color: var(--color-muted-text);
      font-weight: 600;
    }

    .site-nav a:hover,
    .site-nav a[aria-current="page"] {
      color: var(--color-text);
    }

    .header-actions {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      flex-wrap: wrap;
    }

    .search-form {
      display: flex;
      align-items: center;
      gap: 0.65rem;
      padding: 0.45rem;
      border: 1px solid var(--color-border);
      border-radius: var(--radius-sm);
      background: rgba(255, 255, 255, 0.8);
    }

    .search-form input {
      min-width: 14rem;
      border: 0;
      background: transparent;
      color: var(--color-text);
      padding: 0.35rem 0.55rem;
    }

    .search-form input::placeholder {
      color: var(--color-muted-text);
    }

    .button,
    .button-secondary {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.5rem;
      min-height: 2.9rem;
      padding: 0.8rem 1.15rem;
      border-radius: var(--radius-sm);
      border: 1px solid transparent;
      font-weight: 700;
      text-decoration: none;
      cursor: pointer;
      transition: transform 0.18s ease, background-color 0.18s ease, border-color 0.18s ease;
    }

    .button {
      background: var(--color-accent);
      color: #fff;
    }

    .button:hover {
      background: var(--color-accent-strong);
      transform: translateY(-1px);
    }

    .button-secondary {
      background: transparent;
      color: var(--color-text);
      border-color: var(--color-border-strong);
    }

    .button-secondary:hover {
      background: #fff;
      transform: translateY(-1px);
    }

    main {
      padding: 2rem 0 4rem;
    }

    section {
      margin-top: 2rem;
    }

    .hero {
      display: grid;
      grid-template-columns: minmax(0, 1.15fr) minmax(320px, 0.85fr);
      gap: 1.5rem;
      align-items: stretch;
      margin-top: 0;
    }

    .hero-panel,
    .hero-aside,
    .collection-highlight,
    .deal-card,
    .story-card,
    .newsletter-panel,
    .product-card {
      background: rgba(255, 255, 255, 0.78);
      border: 1px solid rgba(216, 206, 194, 0.9);
      box-shadow: var(--shadow-soft);
      backdrop-filter: blur(18px);
    }

    .hero-panel {
      position: relative;
      overflow: hidden;
      padding: clamp(1.8rem, 3vw, 3rem);
      border-radius: var(--radius-xl);
      min-height: 34rem;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
    }

    .hero-panel::before {
      content: "";
      position: absolute;
      inset: 0;
      background:
        radial-gradient(circle at 15% 20%, rgba(255, 255, 255, 0.9) 0 12%, rgba(255, 255, 255, 0) 13%),
        radial-gradient(circle at 88% 16%, rgba(201, 106, 52, 0.18) 0 17%, rgba(201, 106, 52, 0) 18%),
        linear-gradient(135deg, rgba(216, 230, 226, 0.95), rgba(255, 255, 255, 0.6) 42%, rgba(247, 227, 215, 0.95));
      z-index: 0;
    }

    .hero-panel > * {
      position: relative;
      z-index: 1;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.4rem 0.8rem;
      border-radius: var(--radius-sm);
      background: rgba(255, 255, 255, 0.78);
      color: var(--color-muted-text);
      font-size: 0.92rem;
      font-weight: 700;
      width: fit-content;
    }

    .hero h1 {
      margin: 1rem 0 0.9rem;
      max-width: 11ch;
      font-size: clamp(2.7rem, 5vw, 5.1rem);
      line-height: 0.95;
      letter-spacing: -0.05em;
    }

    .hero-copy {
      max-width: 34rem;
      margin: 0;
      font-size: 1.08rem;
      color: var(--color-muted-text);
    }

    .hero-actions,
    .hero-metrics,
    .product-actions,
    .section-top {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 0.8rem;
    }

    .hero-actions {
      margin-top: 1.5rem;
    }

    .hero-metrics {
      margin: 2rem 0 0;
      gap: 1rem;
    }

    .metric {
      min-width: 9rem;
      padding: 0.95rem 1rem;
      border-radius: var(--radius-md);
      background: rgba(255, 255, 255, 0.76);
      border: 1px solid rgba(216, 206, 194, 0.95);
    }

    .metric strong {
      display: block;
      font-size: 1.2rem;
      margin-bottom: 0.2rem;
    }

    .hero-aside {
      border-radius: var(--radius-xl);
      overflow: hidden;
      display: grid;
      grid-template-rows: 1fr auto;
    }

    .hero-visual {
      min-height: 21rem;
      background:
        radial-gradient(circle at 28% 28%, #fff8f2 0 16%, #fff8f200 17%),
        radial-gradient(circle at 74% 24%, #d8e6e2 0 18%, #d8e6e200 19%),
        linear-gradient(160deg, #b9d2cb 0%, #f8eee5 52%, #f3ddd1 100%);
      position: relative;
    }

    .hero-visual::before,
    .hero-visual::after {
      content: "";
      position: absolute;
      border-radius: 1.5rem;
      box-shadow: var(--shadow-card);
      border: 1px solid rgba(31, 28, 24, 0.08);
    }

    .hero-visual::before {
      width: 46%;
      height: 58%;
      right: 14%;
      bottom: 12%;
      background: linear-gradient(180deg, #7c674f, #514130);
      transform: rotate(-10deg);
    }

    .hero-visual::after {
      width: 30%;
      height: 26%;
      left: 16%;
      bottom: 18%;
      background: linear-gradient(180deg, #e7ceb9, #d7a983);
    }

    .hero-aside-copy {
      padding: 1.5rem;
    }

    .hero-aside-copy h2,
    .section-heading,
    .newsletter-panel h2 {
      margin: 0;
      font-size: clamp(1.5rem, 2.4vw, 2.15rem);
      letter-spacing: -0.03em;
    }

    .section-lead,
    .hero-aside-copy p,
    .story-card p,
    .newsletter-panel p,
    .product-description,
    .meta-text {
      margin: 0.6rem 0 0;
      color: var(--color-muted-text);
    }

    .collections-grid,
    .product-grid,
    .deals-grid,
    .editorial-grid {
      display: grid;
      gap: 1.2rem;
    }

    .collections-grid {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .collection-highlight,
    .deal-card,
    .story-card,
    .newsletter-panel,
    .product-card {
      border-radius: var(--radius-lg);
    }

    .collection-highlight {
      padding: 1.4rem;
      min-height: 14rem;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      background:
        linear-gradient(160deg, rgba(255, 255, 255, 0.88), rgba(255, 255, 255, 0.74)),
        var(--collection-gradient, linear-gradient(160deg, #e6eee9, #f7e6da));
    }

    .collection-highlight a {
      font-weight: 700;
    }

    .section-top {
      justify-content: space-between;
      margin-bottom: 1rem;
    }

    .filter-group {
      display: flex;
      flex-wrap: wrap;
      gap: 0.65rem;
    }

    .filter-button {
      border: 1px solid var(--color-border);
      border-radius: var(--radius-sm);
      background: rgba(255, 255, 255, 0.85);
      padding: 0.7rem 1rem;
      color: var(--color-muted-text);
      font-weight: 700;
      cursor: pointer;
    }

    .filter-button[aria-pressed="true"] {
      background: var(--color-text);
      border-color: var(--color-text);
      color: #fff;
    }

    .product-grid {
      grid-template-columns: repeat(4, minmax(0, 1fr));
      list-style: none;
      padding: 0;
      margin: 0;
    }

    .product-card {
      padding: 1rem;
      display: flex;
      flex-direction: column;
      gap: 0.9rem;
      box-shadow: var(--shadow-card);
    }

    .product-image {
      aspect-ratio: 1 / 1.05;
      border-radius: var(--radius-md);
      overflow: hidden;
      background: var(--product-backdrop, linear-gradient(180deg, #ede6dc, #d8cfc4));
      border: 1px solid rgba(31, 28, 24, 0.06);
    }

    .product-copy {
      display: flex;
      flex-direction: column;
      gap: 0.45rem;
      flex: 1;
    }

    .product-tag,
    .price-tag,
    .deal-tag {
      width: fit-content;
      padding: 0.3rem 0.65rem;
      border-radius: var(--radius-sm);
      font-size: 0.84rem;
      font-weight: 800;
      letter-spacing: 0.01em;
    }

    .product-tag {
      background: var(--color-surface-alt);
      color: var(--color-muted-text);
    }

    .price-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 0.5rem;
      margin-top: auto;
    }

    .price-tag {
      background: var(--color-accent-soft);
      color: var(--color-accent-strong);
    }

    .save-button {
      min-width: 5.5rem;
    }

    .save-button[aria-pressed="true"] {
      background: var(--color-highlight-soft);
      border-color: #d9b195;
      color: #8a3e16;
    }

    .deals-grid {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .deal-card {
      padding: 1.5rem;
      min-height: 16rem;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      background:
        linear-gradient(160deg, rgba(255, 255, 255, 0.88), rgba(255, 255, 255, 0.74)),
        var(--deal-gradient, linear-gradient(160deg, #f3e5da, #e6efe9));
    }

    .deal-tag {
      background: rgba(255, 255, 255, 0.82);
      color: var(--color-highlight);
      border: 1px solid rgba(201, 106, 52, 0.3);
    }

    .editorial-grid {
      grid-template-columns: 1.2fr 1.2fr 0.9fr;
      align-items: stretch;
    }

    .story-card,
    .newsletter-panel {
      padding: 1.5rem;
    }

    .story-card h3,
    .product-name,
    .deal-card h3 {
      margin: 0;
      font-size: 1.22rem;
      letter-spacing: -0.03em;
    }

    .product-name a {
      text-decoration: none;
    }

    .product-name a:hover,
    .story-card a:hover,
    .collection-highlight a:hover,
    .deal-card a:hover {
      text-decoration: underline;
    }

    .story-card .meta-text {
      font-size: 0.92rem;
    }

    .newsletter-form {
      display: grid;
      gap: 0.75rem;
      margin-top: 1rem;
    }

    .newsletter-form label {
      font-weight: 700;
    }

    .newsletter-form input {
      width: 100%;
      padding: 0.9rem 1rem;
      border-radius: 1rem;
      border: 1px solid var(--color-border-strong);
      background: #fff;
      color: var(--color-text);
    }

    .inline-note {
      min-height: 1.5rem;
      margin: 0;
      color: var(--color-muted-text);
      font-size: 0.95rem;
    }

    .site-footer {
      padding: 2rem 0 3rem;
      border-top: 1px solid var(--color-border);
    }

    .footer-grid {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: 1rem;
      color: var(--color-muted-text);
    }

    .footer-grid nav ul {
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
      list-style: none;
      margin: 0;
      padding: 0;
    }

    .visually-hidden {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0 0 0 0);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 1040px) {
      .hero,
      .editorial-grid {
        grid-template-columns: 1fr;
      }

      .collections-grid,
      .deals-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .product-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }
    }

    @media (max-width: 720px) {
      .site-shell {
        width: min(calc(100% - 1rem), var(--max-width));
      }

      .promo-content,
      .masthead,
      .section-top,
      .price-row {
        align-items: flex-start;
      }

      .collections-grid,
      .deals-grid,
      .product-grid {
        grid-template-columns: 1fr;
      }

      .search-form {
        width: 100%;
      }

      .search-form input {
        min-width: 0;
        width: 100%;
      }

      .hero-panel {
        min-height: auto;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      html {
        scroll-behavior: auto;
      }

      *,
      *::before,
      *::after {
        animation: none !important;
        transition: none !important;
      }
    }

    @media (forced-colors: active) {
      body {
        background: Canvas;
        color: CanvasText;
      }

      .promo-bar,
      .site-header,
      .hero-panel,
      .hero-aside,
      .collection-highlight,
      .deal-card,
      .story-card,
      .newsletter-panel,
      .product-card,
      .search-form,
      .filter-button,
      .button,
      .button-secondary {
        background: Canvas;
        color: CanvasText;
        border: 1px solid ButtonBorder;
        box-shadow: none;
      }

      .button,
      .button-secondary,
      .filter-button[aria-pressed="true"] {
        background: ButtonFace;
        color: ButtonText;
      }

      a {
        color: LinkText;
      }

      a:focus-visible,
      button:focus-visible,
      input:focus-visible {
        outline: 3px solid Highlight;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <div class="promo-bar" id="promo-bar">
