    const statusMessage = document.getElementById('status-message');
    const promoBar = document.getElementById('promo-bar');
    const dismissPromoButton = document.getElementById('dismiss-promo');
    const filterButtons = Array.from(document.querySelectorAll('.filter-button'));
    const productCards = Array.from(document.querySelectorAll('.product-card'));
    const featuredSummary = document.getElementById('featured-summary');
    const addToBagButtons = Array.from(document.querySelectorAll('.add-to-bag'));
    const saveButtons = Array.from(document.querySelectorAll('.save-button'));
    const searchForm = document.getElementById('search-form');
    const siteSearch = document.getElementById('site-search');
    const newsletterForm = document.getElementById('newsletter-form');
    const newsletterEmail = document.getElementById('newsletter-email');
    const newsletterNote = document.getElementById('newsletter-note');

    function announce(message) {
      statusMessage.textContent = '';
      window.requestAnimationFrame(() => {
        statusMessage.textContent = message;
      });
    }

    function updateFeaturedSummary(activeFilter) {
      const visibleProducts = productCards.filter((card) => !card.hidden).length;
      const label = activeFilter === 'all'
        ? 'all categories'
        : activeFilter.charAt(0).toUpperCase() + activeFilter.slice(1);

      featuredSummary.textContent = activeFilter === 'all'
        ? `Showing ${visibleProducts} featured products across all categories.`
        : `Showing ${visibleProducts} featured products in ${label}.`;
    }

    dismissPromoButton.addEventListener('click', () => {
      promoBar.hidden = true;
      announce('Promo banner dismissed.');
    });

    filterButtons.forEach((button) => {
      button.addEventListener('click', () => {
        const activeFilter = button.dataset.filter;

        filterButtons.forEach((item) => {
          item.setAttribute('aria-pressed', String(item === button));
        });

        productCards.forEach((card) => {
          card.hidden = activeFilter !== 'all' && card.dataset.category !== activeFilter;
        });

        updateFeaturedSummary(activeFilter);
        announce(`Featured products filtered to ${activeFilter === 'all' ? 'all categories' : activeFilter}.`);
      });
    });

    addToBagButtons.forEach((button) => {
      button.addEventListener('click', () => {
        announce(`${button.dataset.product} added to bag.`);
      });
    });

    saveButtons.forEach((button) => {
      button.addEventListener('click', () => {
        const isSaved = button.getAttribute('aria-pressed') === 'true';
        const nextState = !isSaved;
        const productName = button.dataset.product;
        const visibleLabel = nextState ? 'Saved' : 'Save';

        button.setAttribute('aria-pressed', String(nextState));
        button.textContent = visibleLabel;
        button.setAttribute('aria-label', `${visibleLabel}: ${productName}`);

        announce(nextState ? `${productName} saved for later.` : `${productName} removed from saved items.`);
      });

      button.setAttribute('aria-label', `Save: ${button.dataset.product}`);
    });

    searchForm.addEventListener('submit', (event) => {
      event.preventDefault();
      const term = siteSearch.value.trim();

      if (!term) {
        announce('Enter a search term to explore the collection.');
        siteSearch.focus();
        return;
      }

      announce(`Search for ${term} is a demo preview in this concept page.`);
    });

    newsletterForm.addEventListener('submit', (event) => {
      event.preventDefault();

      if (!newsletterForm.reportValidity()) {
        return;
      }

      const email = newsletterEmail.value.trim();
      newsletterNote.textContent = `Thanks for joining, ${email}. Member updates will land in your inbox soon.`;
      announce(`Joined the list with ${email}.`);
      newsletterForm.reset();
    });
  </script>
